// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import org.eclipse.rdf4j.sail.lmdb.AdjacencySourceScanner.GroupConsumer;
import org.eclipse.rdf4j.sail.lmdb.AdjacencySourceScanner.ScanRange;
import org.eclipse.rdf4j.sail.lmdb.TxnManager.Txn;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Tests that {@link LmdbAdjacencyTripleStoreScanner#planRanges} cuts a skewed store into ranges of roughly equal
 * statement count rather than equal key space, and that the resulting ranges still tile the index exactly once.
 */
class LmdbAdjacencyWeightedRangePlanTest {

	private static final long[] PREDICATES = { 10, 20, 30, 40, 50 };
	private static final int HEAVY_INDEX = 2;
	private static final int HEAVY_STATEMENTS = 20_000;
	private static final int LIGHT_STATEMENTS = 200;
	private static final int TOTAL_STATEMENTS = HEAVY_STATEMENTS + (PREDICATES.length - 1) * LIGHT_STATEMENTS;
	private static final int TARGET_RANGES = 16;

	@TempDir
	File dataDir;

	private TripleStore tripleStore;

	@AfterEach
	void tearDown() throws Exception {
		if (tripleStore != null) {
			tripleStore.close();
		}
	}

	@Test
	void theDominantPredicateIsSpreadOverManyRanges() throws Exception {
		tripleStore = skewedStore();

		try (Txn txn = tripleStore.getTxnManager().createReadTxn()) {
			LmdbAdjacencyTripleStoreScanner scanner = new LmdbAdjacencyTripleStoreScanner(tripleStore, txn,
					tripleStore.getDataRevision());
			ScanRange[] ranges = scanner.planRanges(LmdbAdjacencyPlane.PLANE_INCOMING_EXPLICIT,
					LmdbAdjacencyCoverage.full(), PREDICATES, TARGET_RANGES);

			assertThat(ranges).hasSizeGreaterThan(1);
			List<RangeContents> contents = replay(scanner, ranges);

			long rangesHoldingTheHeavyPredicate = contents.stream()
					.filter(range -> range.predicates.contains(PREDICATES[HEAVY_INDEX]))
					.count();
			assertThat(rangesHoldingTheHeavyPredicate)
					.as("the predicate holding 96%% of the statements must not be one worker's problem")
					.isGreaterThan(1);

			long heaviestRange = contents.stream().mapToLong(range -> range.statements).max().orElseThrow();
			double ideal = (double) TOTAL_STATEMENTS / TARGET_RANGES;
			assertThat((double) heaviestRange)
					.as("heaviest planned range against an ideal share of %s", ideal)
					.isLessThan(3 * ideal);
		}
	}

	@Test
	void theWeightedPlanStillTilesTheIndexExactlyOnce() throws Exception {
		tripleStore = skewedStore();

		try (Txn txn = tripleStore.getTxnManager().createReadTxn()) {
			LmdbAdjacencyTripleStoreScanner scanner = new LmdbAdjacencyTripleStoreScanner(tripleStore, txn,
					tripleStore.getDataRevision());
			ScanRange[] ranges = scanner.planRanges(LmdbAdjacencyPlane.PLANE_INCOMING_EXPLICIT,
					LmdbAdjacencyCoverage.full(), PREDICATES, TARGET_RANGES);

			List<RangeContents> contents = replay(scanner, ranges);
			long visited = contents.stream().mapToLong(range -> range.statements).sum();
			Set<String> distinct = new HashSet<>();
			for (RangeContents range : contents) {
				distinct.addAll(range.pairs);
			}

			assertThat(visited).isEqualTo(TOTAL_STATEMENTS);
			assertThat(distinct).hasSize(TOTAL_STATEMENTS);
		}
	}

	@Test
	void outgoingPlanesKeepTheirSubjectLeadingPlanWhenNoPredicateLeadingIndexExists() throws Exception {
		tripleStore = skewedStore();

		try (Txn txn = tripleStore.getTxnManager().createReadTxn()) {
			LmdbAdjacencyTripleStoreScanner scanner = new LmdbAdjacencyTripleStoreScanner(tripleStore, txn,
					tripleStore.getDataRevision());
			// spoc is subject leading, so the outgoing plane cannot use predicate boundaries; it must still plan a
			// usable tiling through the pre-existing interpolated splitter.
			ScanRange[] ranges = scanner.planRanges(LmdbAdjacencyPlane.PLANE_OUTGOING_EXPLICIT,
					LmdbAdjacencyCoverage.full(), PREDICATES, TARGET_RANGES);

			assertThat(ranges).hasSizeGreaterThan(1);
			long visited = replay(scanner, ranges).stream().mapToLong(range -> range.statements).sum();
			assertThat(visited).isEqualTo(TOTAL_STATEMENTS);
		}
	}

	private static List<RangeContents> replay(LmdbAdjacencyTripleStoreScanner scanner, ScanRange[] ranges)
			throws Exception {
		List<RangeContents> contents = new ArrayList<>(ranges.length);
		for (ScanRange range : ranges) {
			RangeContents observed = new RangeContents();
			int plane = range.keyRange().indexFieldSeq().startsWith("p")
					? LmdbAdjacencyPlane.PLANE_INCOMING_EXPLICIT
					: LmdbAdjacencyPlane.PLANE_OUTGOING_EXPLICIT;
			scanner.scanRange(plane, LmdbAdjacencyCoverage.full(), range, observed);
			contents.add(observed);
		}
		return contents;
	}

	private static final class RangeContents implements GroupConsumer {

		private final Set<Long> predicates = new HashSet<>();
		private final Set<String> pairs = new HashSet<>();
		private long statements;
		private long key;
		private long predicate;

		@Override
		public void begin(long key, long predicate, int plane) {
			this.key = key;
			this.predicate = predicate;
			predicates.add(predicate);
		}

		@Override
		public void pair(long neighbor, long context) {
			statements++;
			pairs.add(predicate + "|" + key + "|" + neighbor + "|" + context);
		}

		@Override
		public void end() {
		}
	}

	private TripleStore skewedStore() throws Exception {
		TripleStore store = new TripleStore(dataDir, new LmdbStoreConfig("spoc,posc"), null);
		store.startTransaction();
		long subject = 1_000;
		for (int p = 0; p < PREDICATES.length; p++) {
			int statements = p == HEAVY_INDEX ? HEAVY_STATEMENTS : LIGHT_STATEMENTS;
			for (int i = 0; i < statements; i++) {
				store.storeTriple(subject++, PREDICATES[p], 5_000_000 + i, 1, true);
			}
		}
		store.commit();
		return store;
	}
}
